import threading

class SafeCounter:
    def __init__(self):
        self._value = 0
        self._lock = threading.Lock()

    @property
    def value(self):
        with self._lock:
            return self._value

    def increment(self):
        with self._lock:
            self._value += 1

def count_with_threads(n_threads: int, increments: int) -> int:
    counter = SafeCounter()
    threads = []

    for _ in range(n_threads):
        thread = threading.Thread(target=lambda: [counter.increment() for _ in range(increments)])
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return counter.value
